"""Network mock for isolated component testing.

Simulates message passing with configurable latency, packet loss,
and reordering to test network resilience without real sockets.
"""

import asyncio
import random
import time
from collections import deque
from dataclasses import dataclass, field
from typing import Dict, List, Optional, Any, Callable
from enum import Enum


class MessageType(Enum):
    REQUEST = "request"
    RESPONSE = "response"
    BROADCAST = "broadcast"
    HEARTBEAT = "heartbeat"


@dataclass
class Message:
    """Network message envelope."""
    msg_id: str
    msg_type: MessageType
    sender: str
    receiver: str
    payload: Dict[str, Any]
    timestamp: float = field(default_factory=time.time)
    ttl: int = 3


class NetworkConfig:
    """Configuration for network simulation."""
    
    def __init__(
        self,
        latency_ms: tuple[float, float] = (1.0, 10.0),
        packet_loss_rate: float = 0.0,
        reorder_rate: float = 0.0,
        max_queue_size: int = 1000,
        seed: int = 42
    ):
        self.latency_ms = latency_ms
        self.packet_loss_rate = packet_loss_rate
        self.reorder_rate = reorder_rate
        self.max_queue_size = max_queue_size
        self.seed = seed
        self._rng = random.Random(seed)


class NetworkMock:
    """Simulated network for isolated testing."""
    
    def __init__(self, config: Optional[NetworkConfig] = None):
        self.config = config or NetworkConfig()
        self._rng = self.config._rng
        self._queues: Dict[str, deque] = {}
        self._delivered: List[Message] = []
        self._dropped: List[Message] = []
        self._handlers: Dict[str, Callable] = {}
        self._message_counter = 0
        self._lock = asyncio.Lock()
        self._virtual_time = 0.0
    
    async def send(self, message: Message) -> bool:
        """Send a message through the simulated network."""
        async with self._lock:
            # Simulate packet loss
            if self._rng.random() < self.config.packet_loss_rate:
                self._dropped.append(message)
                return False
            
            # Simulate latency
            latency = self._rng.uniform(*self.config.latency_ms) / 1000.0
            await asyncio.sleep(latency)
            
            # Simulate reordering
            if self._rng.random() < self.config.reorder_rate:
                # Delay message by putting it at back of queue
                self._queues.setdefault(message.receiver, deque()).append(
                    (message, time.time() + self._rng.uniform(0.01, 0.1))
                )
            else:
                self._queues.setdefault(message.receiver, deque()).append(
                    (message, time.time())
                )
            
            # Check queue size
            queue = self._queues[message.receiver]
            if len(queue) > self.config.max_queue_size:
                # Drop oldest message
                oldest = queue.popleft()
                self._dropped.append(oldest[0])
            
            self._message_counter += 1
            return True
    
    async def receive(self, node_id: str) -> Optional[Message]:
        """Receive next message for a node."""
        async with self._lock:
            queue = self._queues.get(node_id)
            if not queue:
                return None
            
            # Check for messages ready to deliver
            now = time.time()
            while queue:
                msg, deliver_at = queue[0]
                if deliver_at <= now:
                    queue.popleft()
                    self._delivered.append(msg)
                    return msg
                else:
                    # Message not ready yet
                    return None
            
            return None
    
    async def broadcast(self, sender: str, message: Message) -> List[bool]:
        """Broadcast message to all nodes."""
        results = []
        for node_id in self._queues.keys():
            if node_id != sender:
                msg_copy = Message(
                    msg_id=f"{message.msg_id}_{node_id}",
                    msg_type=message.msg_type,
                    sender=sender,
                    receiver=node_id,
                    payload=message.payload.copy(),
                    timestamp=message.timestamp,
                    ttl=message.ttl
                )
                results.append(await self.send(msg_copy))
        return results
    
    def register_handler(self, msg_type: MessageType, handler: Callable) -> None:
        """Register message handler."""
        self._handlers[msg_type.value] = handler
    
    async def process_until_idle(self, timeout: float = 1.0) -> None:
        """Process all pending messages until queues are empty."""
        deadline = time.time() + timeout
        while time.time() < deadline:
            processed = False
            for node_id in list(self._queues.keys()):
                msg = await self.receive(node_id)
                if msg:
                    handler = self._handlers.get(msg.msg_type.value)
                    if handler:
                        await handler(msg)
                    processed = True
            if not processed:
                break
            await asyncio.sleep(0.001)
    
    def state(self) -> Dict[str, Any]:
        """Capture current state for snapshot/restore."""
        return {
            "delivered": len(self._delivered),
            "dropped": len(self._dropped),
            "queued": sum(len(q) for q in self._queues.values()),
            "message_counter": self._message_counter,
            "virtual_time": self._virtual_time
        }
    
    def restore(self, state: Dict[str, Any]) -> None:
        """Restore from snapshot."""
        self._delivered = self._delivered[:state["delivered"]]
        self._dropped = self._dropped[:state["dropped"]]
        self._message_counter = state["message_counter"]
        self._virtual_time = state["virtual_time"]
    
    def reset(self) -> None:
        """Reset mock to initial state."""
        self._queues.clear()
        self._delivered.clear()
        self._dropped.clear()
        self._message_counter = 0
        self._virtual_time = 0.0
        self._rng = random.Random(self.config.seed)


def create_network_mock(seed: int = 42, **kwargs) -> NetworkMock:
    """Factory function for NetworkMock."""
    config = NetworkConfig(seed=seed, **kwargs)
    return NetworkMock(config)